-- Phase 2H: commercial booking snapshots and normalized operational workspaces.
CREATE TABLE IF NOT EXISTS catering_bookings (id varchar PRIMARY KEY DEFAULT gen_random_uuid(), inquiry_id varchar NOT NULL REFERENCES catering_inquiries(id) ON DELETE RESTRICT, provider_id varchar NOT NULL REFERENCES users(id) ON DELETE RESTRICT, customer_id varchar NOT NULL REFERENCES users(id) ON DELETE RESTRICT, status varchar(24) NOT NULL DEFAULT 'pending_confirmation' CHECK (status IN ('pending_confirmation','confirmed','completed','cancelled')), event_date date NOT NULL, event_type varchar(120), guest_count integer CHECK (guest_count IS NULL OR guest_count > 0), package_snapshot jsonb, agreed_price numeric(12,2), currency varchar(3) NOT NULL DEFAULT 'USD', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT catering_bookings_inquiry_uidx UNIQUE(inquiry_id));
CREATE INDEX IF NOT EXISTS catering_bookings_participant_idx ON catering_bookings(provider_id, customer_id);
CREATE TABLE IF NOT EXISTS catering_booking_details (booking_id varchar PRIMARY KEY REFERENCES catering_bookings(id) ON DELETE CASCADE, venue_name varchar(160), venue_address varchar(240), venue_city varchar(100), venue_state varchar(100), venue_postal_code varchar(24), venue_instructions text, arrival_time varchar(5), service_start_time varchar(5), service_end_time varchar(5), setup_notes text, access_notes text, kitchen_available boolean, refrigeration_available boolean, power_available boolean, water_available boolean, indoor_outdoor varchar(16) CHECK (indoor_outdoor IS NULL OR indoor_outdoor IN ('indoor','outdoor','both')), customer_notes text, provider_notes text, updated_at timestamptz NOT NULL DEFAULT now(), CHECK (arrival_time IS NULL OR arrival_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'), CHECK (service_start_time IS NULL OR service_start_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'), CHECK (service_end_time IS NULL OR service_end_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'));
CREATE TABLE IF NOT EXISTS catering_booking_tasks (id varchar PRIMARY KEY DEFAULT gen_random_uuid(), booking_id varchar NOT NULL REFERENCES catering_bookings(id) ON DELETE CASCADE, title varchar(160) NOT NULL, description text, status varchar(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')), visibility varchar(16) NOT NULL DEFAULT 'provider' CHECK(visibility IN ('provider','shared')), due_date date, due_time varchar(5), sort_order integer NOT NULL DEFAULT 0 CHECK(sort_order >= 0), created_by varchar NOT NULL REFERENCES users(id) ON DELETE RESTRICT, source varchar(16) NOT NULL DEFAULT 'provider' CHECK(source IN ('provider','system')), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(due_time IS NULL OR due_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'));
CREATE INDEX IF NOT EXISTS catering_booking_tasks_booking_sort_idx ON catering_booking_tasks(booking_id, sort_order, id);
CREATE TABLE IF NOT EXISTS catering_booking_activity (id varchar PRIMARY KEY DEFAULT gen_random_uuid(), booking_id varchar NOT NULL REFERENCES catering_bookings(id) ON DELETE CASCADE, actor_user_id varchar REFERENCES users(id) ON DELETE SET NULL, event_type varchar(48) NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', visibility varchar(16) NOT NULL DEFAULT 'shared' CHECK(visibility IN ('provider','shared')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS catering_booking_activity_page_idx ON catering_booking_activity(booking_id, created_at DESC, id DESC);
